// Canonical HMAC SHA-256 Signature Verification
const crypto = require('crypto');

function canonicalStringify(obj) {
  if (obj === null || typeof obj !== 'object') {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return '[' + obj.map(canonicalStringify).join(',') + ']';
  }
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStringify(obj[k])).join(',') + '}';
}

const secret = $env.N8N_WEBHOOK_SECRET || '';
const item = $input.item.json;
const headers = item.headers || ($node['Webhook Ingest'] && $node['Webhook Ingest'].json.headers) || {};
const payload = item.body || item;

const signature = headers['x-st-signature'] || headers['X-ST-Signature'];
const timestamp = headers['x-st-timestamp'] || headers['X-ST-Timestamp'];
const deliveryId = headers['x-st-delivery-id'] || headers['X-ST-Delivery-Id'] || payload.deliveryId;

if (!signature || !timestamp || !deliveryId) {
  throw new Error('Missing required security headers (X-ST-Signature, X-ST-Timestamp, X-ST-Delivery-Id)');
}

// Verify timestamp freshness (within 5 minutes = 300000ms)
const timeDiff = Math.abs(Date.now() - new Date(timestamp).getTime());
if (isNaN(timeDiff) || timeDiff > 300000) {
  throw new Error('Timestamp stale or malformed: ' + timestamp);
}

// Canonical string calculation
const canonicalPayload = canonicalStringify(payload);
const stringToSign = `${timestamp}.${deliveryId}.${canonicalPayload}`;
const calculated = crypto.createHmac('sha256', secret).update(stringToSign, 'utf8').digest('hex');

// Constant-time comparison
const sigBuf = Buffer.from(signature.trim().toLowerCase(), 'hex');
const calcBuf = Buffer.from(calculated.toLowerCase(), 'hex');
if (sigBuf.length !== calcBuf.length || !crypto.timingSafeEqual(sigBuf, calcBuf)) {
  throw new Error('HMAC signature verification failed: Invalid payload signature');
}

return [{
  json: {
    ...payload,
    headers
  }
}];

// Build authenticated callback payload to report SENT status
const crypto = require('crypto');

function canonicalStringify(obj) {
  if (obj === null || typeof obj !== 'object') {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return '[' + obj.map(canonicalStringify).join(',') + ']';
  }
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStringify(obj[k])).join(',') + '}';
}

const secret = $env.N8N_WEBHOOK_SECRET || '';
const source = $node['Verify Canonical Signature'].json;
const deliveryId = source.deliveryId;
const callbackUrl = source.callbackUrl || 'https://st-solutions-2ovq.onrender.com/api/v1/automation/callback';
const timestamp = new Date().toISOString();

const callbackBody = {
  deliveryId: deliveryId,
  status: 'SENT',
  responseCode: 200,
  providerMessageId: 'n8n-smtp-' + Date.now(),
  deliveredAt: timestamp
};

const canonical = canonicalStringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${deliveryId}.${canonical}`, 'utf8').digest('hex');

return [{
  json: {
    deliveryId,
    callbackUrl,
    callbackBody,
    headers: {
      'Content-Type': 'application/json',
      'X-ST-Signature': signature,
      'X-ST-Timestamp': timestamp,
      'X-ST-Delivery-Id': deliveryId
    }
  }
}];
